def get_current_log_html_timestamp():
    """
    Get current timestamp in formatted string.

    Important: used with estimation to 2nd decimal place in log.html file.
    """
    timestamp_accurate = datetime.now().strftime("%H:%M:%S.%f")
    try:
        timestamp = timestamp_accurate.split(".")[0] + "." + round(float("0." + timestamp_accurate.split(".")[1]), 2).__str__().split(".")[1]
    except Exception:
        timestamp = str(timestamp_accurate)[:-4]  # Fallback to 4 digits from microseconds
    return timestamp


def collect_kw_data(method):
    """
    Decorator to collect keyword data for robot API.

    :param method: method: method to wrap
    :return: method: wrapped method
    """
    @functools.wraps(method)
    def wrapped_metadata_method(inst, *args, **kwargs):
        kw_name_words = [word.capitalize() for word in str(method.__name__).split("_")]
        inst._kw_data.kw_name = " ".join(kw_name_words)
        kw_start_time = time.time()
        try:
            ret_val = method(inst, *args, **kwargs)
        except Exception as e:
            e_timestamp = get_current_log_html_timestamp()
            inst._kw_data.kw_duration = time.time() - kw_start_time
            report = inst._kw_data.report_use(error=e)
            if len(report) != 0:
                report["kw_error_timestamp"] = e_timestamp
                report_text = inst._kw_data.format_info(report=report, error=e, error_nr=len(inst._fails) + 1)
                inst._fails.append(report_text)
            raise e
        else:
            inst._kw_data.kw_duration = time.time() - kw_start_time
            inst._kw_data.report_use()
        return ret_val
    return wrapped_metadata_method


def log_kw_data(data, message=None):
    """
    Log data to ute_ue.kw_data.log.

    :param data: dict: KW data
    :param message: Summary message log
    """
    logger = logging.getLogger('ute_ue.kw_data')
    logger.info(message, **data)


def get_windows_version() -> Union[str, None]:  # noqa: C901
    """
    Get Windows version and build number.
    :return: str: Windows version and build number, e.g. "10, Build 19042" (None for non-Windows systems)
    """
    windows_10_build_main = 10
    if platform.system().lower() != "windows":
        return None
    os_build_version = platform.version().split(" ")[-1]  # Get build number (which is in the end in earlier Windows)
    os_release_main = int(str(platform.release()).split(".")[0])  # Get major (in general it supposes to be only major)
    if os_release_main == windows_10_build_main and len(os_build_version.split(".")) == 3:
        # Windows 10 and 11
        with suppress(ValueError):
            os_build_version_subminor = int(os_build_version.split(".")[-1])
            if os_build_version_subminor >= WINDOWS_11_MIN_BUILD:
                return f"11, Build {os_build_version}"
            elif os_build_version_subminor >= WINDOWS_10_MIN_BUILD:
                return f"10, Build {os_build_version}"
            else:
                return f"Unknown <10, Build {os_build_version}"
    elif os_release_main > 0 and os_release_main != windows_10_build_main:
        return f"{os_release_main}, Build {os_build_version}"
    return f"{os_release_main}?, Build {os_build_version}"


def _merge_str_vals(*args):
    for val in args:
        if val:
            return val
    return None


class DistributionsCache:
    """
    Simplified singleton class to handle and cache importlib.metadata.distributions
    """
    _importlib_metadata_distributions = None

    @classmethod
    def pip_distributions_with_versions(cls):
        if not cls._importlib_metadata_distributions:
            cls._importlib_metadata_distributions = [{"name": d.metadata['Name'], "version": d.version}
                                                     for d in importlib.metadata.distributions()]
        return cls._importlib_metadata_distributions


@dataclass
class DataCommon:
    """Generic scope KW data use class."""
    # Dynamic data related to test scenario
    quantity: int = 0
    unique = True

    def __str__(self):
        return str(asdict(self))

    def __repr__(self):
        return asdict(self)

    def count_up(self):
        """Additional feature to track if KW used anymore and how many times."""
        self.quantity += 1
        if self.quantity > 1:
            self.unique = False


class HtmlReport:
    """HTML Report generation class."""
    TEMPLATE_FAILED_KW = """
        <div id="ute_ue_errors-{error_nr}">
            <div class="element-header closed" onclick="toggleElement('ute_ue_errors-{error_nr}')">
                <div class="element-header-toggle" title="Toggle visibility of the error details and circumstances."></div>
                <div class="element-header-left" title="ERROR">
                    <span class="label debug">{tag}</span>
                    <span class="name">{error_nr}) {error_message}</span>
                </div>
            </div>
            <div class="children" style="display: none;"><table class="messages">
                <tr id="ute_ue_error-{error_nr}" class="message-row">
                    <td class="message">{table_html}</td>
                    <td class="select-message" onclick="javascript:selectMessage('ute_ue_error-{error_nr}')"
                        title="Select error text"><div></div></td>
                </tr>
            </table></div>
        </div>
        """.replace("  ", "").replace("\n", "")

    def __init__(self, report: dict, error: Exception, error_nr: int):
        self.report = report
        self.error = error
        self.error_nr = error_nr
        self.tag = (
            report.get("ue_pc", {}).get("access_name") or report.get("plugin_version") if report.get("plugin_name") else "ute_ue"
        ).upper()

        table_skip_keys = ["level", ]
        for key in table_skip_keys:
            if key in self.report:
                self.report.pop(key)

    @staticmethod
    def _to_display_str(val):
        if val is None:
            return "Unknown"
        if isinstance(val, bool):
            return "true" if val else "false"
        return str(val)

    @staticmethod
    def _escape_and_preserve_lines(val_str: str) -> str:
        return html.escape(val_str).replace("\n", "<br/>")

    def _html_table(self, kw_names: dict, header: str, sub_element: str = None) -> str:
        """
        Generate HTML table for given information.
        :param kw_names: dict: KW names mapping
        :param header: str: Table header
        :param sub_element: str: Sub-element in self.report dict
        :return: str: HTML table for given information
        """
        table_html = ""
        rows = []
        data = self.report.get(sub_element, {}) if sub_element else self.report
        if not sub_element or (sub_element and sub_element in self.report):
            for key in kw_names:
                if key in data:
                    value = data.pop(key)
                    rows.append(
                        f"<tr><td id=\"generated\">{html.escape(kw_names[key])}: </td>"
                        f"<td>{self._escape_and_preserve_lines(str(value))}</td></tr>"
                    )
            table_html = (
                f"<span><b>{header}:</b></span><table>"
                "<tbody>" + "".join(rows) + "</tbody></table>"
            )
            self.report.pop(sub_element, None)
        return table_html

    def _html_table_other_info(self) -> str:
        """
        Generate HTML table for other information (still left in `report` element).
        :return: str: HTML table for other information
        """
        rows_other = []
        table_other_html = ""
        if self.report:
            for key, value in self.report.items():
                rows_other.append(
                    f"<tr><td id=\"generated\">{str(html.escape(key)).capitalize()}: </td>"
                    f"<td class=\"message\">{self._escape_and_preserve_lines(str(value))}</td></tr>"
                )
            table_other_html = (
                "<span><b>Other Information:</b></span><table>"
                "<tbody>" + "".join(rows_other) + "</tbody></table>"
            )
        return table_other_html

    def _format_error_message(self) -> str:
        """
        Format error message for HTML report.
        :return: str: Formatted error message
        """
        error_message = ""
        error = self._escape_and_preserve_lines(self._to_display_str(self.error))

        if "jsonrpc failed with" in error:  # Error passed from UE-PC proxy as 'InternalError'
            error_prefix = error.split("call at http")[0] if "call at http" in error else ""
            error = error.replace(error_prefix, "").split("Internal error")[1].strip()
            error_message = error if len(error) < 250 else (error[0:250] + " (...) ")
            return error_prefix + error_message
        return error

    def generate_html_report(self) -> str:
        """
        Generate full HTML report for KW information.
        :return: str: Full HTML report for KW information
        """
        # KW Information table
        table_kw_html = self._html_table(
            kw_names={"ts_name": "Test Suite", "tc_name": "Test Case", "kw_name": "Keyword", "kw_start_timestamp": "Start Timestamp",
                      "kw_error_timestamp": "Exception Timestamp", "kw_duration": "Execution Duration", "logfile": "Logfile", },
            header="Keyword Info"
        )

        # VM Information table
        table_vm_html = self._html_table(
            kw_names={"os": "OS", "py_version": "Python Version", "rf_version": "Robot Framework Version",
                      "plugin_name": "Plugin Name", "plugin_version": "Plugin Version", "libs": "Libraries", },
            header="VM Info"
        )

        # UE_PC Information table
        table_ue_pc_html = self._html_table(
            kw_names={"ip": "IP Address", "port": "UE Proxy Port", "os": "OS", "python_version": "Python Version",
                      "proxy_version": "Proxy Version", "access_name": "Access Name", "access_version": "Access Version",
                      "build_version": "Build Version", "pwd": "Current Working Directory", "user": "User",
                      "cygwin": "Cygwin", "libs": "Libraries", },
            header="UE-PC Info",
            sub_element="ue_pc"
        )

        # UE Information table
        table_ue_html = self._html_table(
            kw_names={"name": "Name", "model": "Model", "os_ver": "OS Version", "naa_ver": "NAA Version",
                      "build_version": "Build Version"},
            header="UE Info",
            sub_element="ue_data"
        )

        # Other Information table (optional)
        table_other_html = self._html_table_other_info()

        table_html = table_kw_html + table_vm_html + table_ue_pc_html + table_ue_html + table_other_html

        if not self.error:
            return table_html

        return self.TEMPLATE_FAILED_KW.strip().format(
            error_nr=self.error_nr,
            tag=self.tag,
            error_message=self._format_error_message(),
            table_html=table_html
        )


class JsonReport:
    """JSON Report generation class."""

    def __init__(self, report: dict, error: Exception):
        self.report = report
        self.error = error
        self.tag = (
            report.get("ue_pc", {}).get("access_name") or report.get("plugin_version") if report.get("plugin_name") else "ute_ue"
        ).upper()

        table_skip_keys = ["level", ]
        for key in table_skip_keys:
            if key in self.report:
                self.report.pop(key)

    def _json_info(self, kw_names: dict, sub_element: str = None) -> dict:
        """
        Generate JSON for given information.
        :param kw_names: dict: KW names mapping
        :param sub_element: str: Sub-element in self.report dict
        :return: dict: JSON for given information
        """
        json_info = {}
        data = self.report.get(sub_element, {}) if sub_element else self.report
        if not sub_element or (sub_element and sub_element in self.report):
            for key in kw_names:
                if key in data:
                    value = data.pop(key)
                    json_info[kw_names[key]] = value
            self.report.pop(sub_element, None)
        return json_info

    def _json_other_info(self) -> dict:
        """
        Generate JSON for other information (still left in `report` element).
        :return: dict: JSON for other information
        """
        json_other = {}
        if self.report:
            for key, value in self.report.items():
                json_other[html.escape(key).capitalize()] = value
        return json_other

    def _format_error_message(self) -> str:
        """
        Format error message for JSON report.
        :return: str: Formatted error message
        """
        if self.error is None:
            return ""

        # `self.error` is typically an Exception instance (e.g. KeyError), not a string.
        # Always convert to string first so substring checks can't raise TypeError.
        error = str(self.error)

        if "jsonrpc failed with" in error:  # Error passed from UE-PC proxy as 'InternalError'
            error_prefix = error.split("call at http")[0] if "call at http" in error else ""
            with suppress(IndexError):
                error = error.replace(error_prefix, "").split("Internal error")[1].strip()
            error_message = error if len(error) < 250 else (error[0:250] + " (...) ")
            return error_prefix + error_message
        return error

    def generate_json_report(self) -> str:
        """
        Generate full JSON report for KW information.
        :return: str: Full JSON report for KW information
        """
        # Note: despite the name, this output is intentionally formatted for
        # console/debug readability (Robot Framework <7.4 path), not strict JSON.
        # Prefer a human-friendly tag (lowercase) for the prefix.
        names_kw = {"ts_name": "Test Suite", "tc_name": "Test Case", "kw_name": "Keyword", "kw_start_timestamp": "Start Timestamp",
                    "kw_error_timestamp": "Exception Timestamp", "kw_duration": "Execution Duration", "logfile": "Logfile", }
        names_vm = {"os": "OS", "py_version": "Python Version", "rf_version": "Robot Framework Version",
                    "plugin_name": "Plugin Name", "plugin_version": "Plugin Version", "libs": "Libraries", }
        names_ue_pc = {"ip": "IP Address", "port": "UE Proxy Port", "os": "OS", "python_version": "Python Version",
                       "proxy_version": "Proxy Version", "access_name": "Access Name", "access_version": "Access Version",
                       "build_version": "Build Version", "pwd": "Current Working Directory", "user": "User", "cygwin": "Cygwin",
                       "libs": "Libraries", }
        names_ue = {"name": "Name", "model": "Model", "os_ver": "OS Version", "naa_ver": "NAA Version", "build_version": "Build Version"}
        raw_tag = (
            (self.report.get("ue_pc", {}) or {}).get("access_name")
            or self.report.get("plugin_name")
            or "ute_ue"
        )
        tag = str(raw_tag).upper()
        info = {
            "KW Info": self._json_info(kw_names=names_kw),
            "VM Info": self._json_info(kw_names=names_vm),
            "UE-PC Info": self._json_info(kw_names=names_ue_pc, sub_element="ue_pc"),
            "UE Info": self._json_info(kw_names=names_ue, sub_element="ue_data"),
        }
        other_info = self._json_other_info()
        if other_info:
            info["Other Information"] = other_info

        # Render without outer braces, one top-level section per line.
        # Use Python repr-style (single quotes), matching existing logs.
        lines = [f"⚠️ [{tag}] {self._format_error_message()}"]
        for section_name, section_payload in info.items():
            lines.append(f"{section_name} → {section_payload}")
        return "\n".join(lines)


