@dataclass
class TestData(DataCommon):
    """ Keyword Test data dataclass."""
    # Static data related to environment or test-suite
    kw_name: str = None
    kw_duration: float = None
    test_suite_name: str = None
    test_case_name: str = None

    # Temporary data
    plugin_name: str = None
    access_name: str = None
    ue_alias: str = None
    vc_alias: str = None
    dt_alias: str = None
    act_test_case: TestCaseData = field(default_factory=TestCaseData)
    act_test_suite: TestSuiteData = field(default_factory=TestSuiteData)

    # Dynamic data related to test scenario
    keywords: dict = field(default_factory=dict)
    vc_ues: dict = field(default_factory=dict)
    dt_ues: dict = field(default_factory=dict)
    logging_bypasses: dict = field(default_factory=dict)

    # Helper data
    _diagnostic_data: dict = field(default_factory=dict)
    _ue_data: dict = field(default_factory=dict)
    _vm_platform_info: str = None
    _vm_distro_info: str = None

    def init_test_suite_data(self, name, rf_file: str = None):
        """Initialize Test Suite Data."""
        self.act_test_case = TestCaseData()
        self.act_test_suite = TestSuiteData()
        self.act_test_suite.robot_file = rf_file.split(os.sep)[-1] if rf_file else None
        self.test_suite_name = name
        os.environ[ENV_TS_NAME] = name
        self.act_test_suite._time_start = time.time()
        # Test Suite begins - StartUp (before Test Cases)
        self.test_case_name = "StartUp"
        os.environ[ENV_TC_NAME] = "StartUp"

    def init_test_case_data(self, name):
        """Initialize Test Case Data."""
        self.act_test_case = TestCaseData()
        self.test_case_name = name
        os.environ[ENV_TC_NAME] = name
        self.act_test_case._time_start = time.time()

    def finish_test_case_data(self):
        """Finish Test Case Data."""
        self.report_test_case()

    def finish_test_suite_data(self):
        """Finish Test Suite Data."""
        self.act_test_suite._time_end = time.time()
        self.act_test_suite.duration = self.act_test_suite._time_end - self.act_test_suite._time_start

    def add_diagnostic_data(self, ue_alias, diag_data):
        """
        Add diagnostic data for environment used -source:  `/about` endpoint.

        :param ue_alias: Alias referring to UE.
        :param diag_data: Data which describes user's environment.
        :return: None
        """
        self._diagnostic_data[ue_alias] = diag_data

    def add_ue_id_data(self, ue_alias, ue_id):
        """
        Add UE ID to diagnostic data for ue_pc's proxy.

        :param ue_alias: Alias referring to UE.
        :param ue_id: UE ID.
        :return: None
        """
        if ue_alias not in self._diagnostic_data:
            self._diagnostic_data[ue_alias] = {}
        self._diagnostic_data[ue_alias].update({'ue_id': str(ue_id).split(":")[-1]})

    def add_rpc_data(self, ue_alias, rpc_client):
        """
        Add RPC info to diagnostic data for ue_pc's proxy.

        :param ue_alias: Alias referring to UE.
        :param rpc_client: RPC client object.
        :return: None
        """
        if ue_alias in self._diagnostic_data:
            self._diagnostic_data[ue_alias].update({'ue_pc_ip': getattr(rpc_client, "hostname", "")})
            self._diagnostic_data[ue_alias].update({'ue_pc_port': getattr(rpc_client, "port", 80)})

    def update_ue_data(self, ue_alias, ue_data):
        """
        Update UE data for UE used -source:  `/get_ue_info` endpoint.

        :param ue_alias: Alias referring to UE.
        :param ue_data: Data which describes information about UE.
        :return: None
        """
        desired_keys = {
            "name", "build_version", "device_model", "commercial_name", "os_version", "mobile_app_version",
            "ue_os_ver", "android_ver"
        }
        if isinstance(ue_data, dict):
            data = {key: value for key, value in ue_data.items() if key in desired_keys}
            self._ue_data[ue_alias] = self._ue_data.get(ue_alias, {})
            self._ue_data[ue_alias].update(data)

    def bind_ue_alias(self, ue_alias, dt_alias: str = None, vc_alias: str = None):
        """
        Add bind between UE and DT or VC alias.

        :param ue_alias: Alias referring to UE.
        :param dt_alias: Alias referring to DT.
        :param vc_alias: Alias referring to VC.
        :return: None
        """
        if dt_alias:
            self.dt_ues[dt_alias] = ue_alias
        elif vc_alias:
            self.vc_ues[vc_alias] = ue_alias

    def set_temp_kw_data(self, ue_alias: str = None, vc_alias: str = None, dt_alias: str = None,
                         plugin_name: str = None, access_name: str = None):
        """
        Set temporary KW data for KW metadata (from Robot API _get_ue(), _get_vc(), _get_dt()).

        :param ue_alias: Alias referring to UE.
        :param vc_alias: Alias referring to VC.
        :param dt_alias: Alias referring to DT.
        :plugin_name: Name of used plugin eg. android, at.
        :access_name: UE type name.
        :return: None
        """
        self.ue_alias = ue_alias
        self.vc_alias = vc_alias
        self.dt_alias = dt_alias

        # general autocorrection of plugin name
        plugin_name = plugin_name or ""
        raw_plugin_name = plugin_name.replace("Ue", "").replace("DataTransfer", "").replace("VoiceCall", "").lower()

        # assign plugin name according to sub-access of AT plugin
        raw_plugin_name = "at" if raw_plugin_name in KNOWN_AT_PLUGIN_ACCESS_NAMES else raw_plugin_name

        # assign plugin according to DT class name
        for plugin in PLUGINS:
            if raw_plugin_name.startswith(f"{plugin}iperf"):
                raw_plugin_name = plugin
                break

        self.plugin_name = raw_plugin_name or None
        self.access_name = access_name

    def check_report_bypass(self):
        """
        Checks if KWs data should be logged.

        :return: bool: true if KWs data should not be logged, false otherwise
        """
        alias = self.ue_alias or self.vc_ues.get(self.vc_alias) or self.dt_ues.get(self.dt_alias)
        return self.logging_bypasses.get(alias, False)

    def report_use(self, error=None):  # noqa: C901
        """
        Report KW use to ute_ue.kw_data.log file.

        :param error: Exception: error object
        :return: dict: Metadata of use KW
        """
        if self.check_report_bypass():
            return {}
        timestamp_kw_start = get_current_log_html_timestamp()
        plugin_name = self.plugin_name
        plugin_version = None
        if plugin_name:
            plugin_version = self._get_plugin_version()

        self.keywords[self.kw_name] = self.keywords.get(self.kw_name, DataCommon())
        self.keywords[self.kw_name].count_up()
        if self.ue_alias:
            alias = self.ue_alias
            data = self.__get_ue_kw_metadata(ue_alias=alias, plugin_name=plugin_name, plugin_version=plugin_version)
        elif self.vc_alias:
            alias = self.vc_ues.get(self.vc_alias)
            data = self.__get_ue_kw_metadata(ue_alias=alias, plugin_name=plugin_name, plugin_version=plugin_version) \
                if alias else {}
        elif self.dt_alias:
            alias = self.dt_ues.get(self.dt_alias)
            data = self.__get_ue_kw_metadata(ue_alias=alias, plugin_name=plugin_name, plugin_version=plugin_version) \
                if alias else {}
        else:
            data = {}
        message = f"KW '{self.kw_name}' used in test case '{self.test_case_name}' "
        message += f"failed with: {error}." if error else "pass."
        data.update({"level": "KW"})
        data.update({"kw_start_timestamp": timestamp_kw_start})
        log_kw_data(data, message=message)
        self.count_up()
        self.act_test_case.count_up()
        self.act_test_suite.count_up()
        # Test Case data
        self.update_test_case_and_suite_data(data, error=error)
        return data

    def update_test_case_and_suite_data(self, data, error=None):
        """
        Update Test Case data.

        :param data: dict: Data to update Test Case and Test Suite data.
        :param error: Exception: error object
        """
        # Get data from KW metadata
        plugin = f"{data.get('plugin_name', None)}=={data.get('plugin_version', '0.0.0')}"
        ip = data.get("ue_pc", {}).get("ip", None)
        ue_pc_os = data.get("ue_pc", {}).get("os", None)
        ue_pc_python = data.get("ue_pc", {}).get("python_version", None)
        proxy = data.get("ue_pc", {}).get("proxy_version", None)
        access_name = data.get('ue_pc', {}).get('access_name', None)
        access_ver = data.get('ue_pc', {}).get('access_version', None)
        access = f"{access_name}=={access_ver}" if access_name else None
        model = data.get("ue_data", {}).get("model", None)
        # Append/Update new data for Test Case and Test Suite
        for scope in [self.act_test_case, self.act_test_suite]:
            scope.plugin_list.append(plugin) \
                if data.get('plugin_name', None) and plugin not in scope.plugin_list else None
            if not scope.py_version:
                scope.py_version = data.get("py_version", None)
            if not scope.rf_version:
                scope.rf_version = data.get("rf_version", None)
            if not scope.os:
                scope.os = data.get("os", None)
            scope.ue_pc_ip_list.append(ip) if ip and ip not in scope.ue_pc_ip_list else ...
            scope.ue_pc_os_list.append(ue_pc_os) if ue_pc_os and ue_pc_os not in scope.ue_pc_os_list else ...
            scope.ue_pc_python_list.append(ue_pc_python) \
                if ue_pc_python and ue_pc_python not in scope.ue_pc_python_list else ...
            scope.ue_pc_proxy_list.append(proxy) if proxy and proxy not in scope.ue_pc_proxy_list else ...
            scope.ue_pc_access_list.append(access) if access and access not in scope.ue_pc_access_list else ...
            scope.ue_models.append(model) if model and model not in scope.ue_models else ...
            scope.status = scope.status and not bool(error)
            if error:
                scope.failed_kws += 1

    def report_test_case(self):
        """Report summary metadata for test case."""
        self.act_test_case._time_end = time.time()
        self.act_test_case.duration = self.act_test_case._time_end - self.act_test_case._time_start
        data = {
            "ts_name": self.__get_ts_name(),
            "tc_name": self.__get_tc_name(),
            "kw_calls": self.act_test_case.quantity,
            "kw_fails": self.act_test_case.failed_kws,
            "py_version": self.act_test_case.py_version,
            "rf_version": self.act_test_case.rf_version,
            "os": self.act_test_case.os,
            "plugins": self.act_test_case.plugin_list,
            "ue_models": self.act_test_case.ue_models,
            "ue_pc_ips": self.act_test_case.ue_pc_ip_list,
            "ue_pc_os": self.act_test_case.ue_pc_os_list,
            "ue_pc_python": self.act_test_case.ue_pc_python_list,
            "ue_pc_proxy": self.act_test_case.ue_pc_proxy_list,
            "ue_pc_access": self.act_test_case.ue_pc_access_list,
            "tc_duration": f'{float(self.act_test_case.duration):.2f}',
            "tc_status": self.act_test_case.status,
            "level": "TC",
        }
        if self.act_test_case.quantity:  # TC which does not use any ute_ue KW suppose to be skipped with file logging
            log_kw_data(data, message="TC")

    def report_test_suite(self):
        """Report summary metadata for test suite."""
        self.act_test_suite._time_end = time.time() if not self.act_test_suite._time_end \
            else self.act_test_suite._time_end
        self.act_test_suite.duration = self.act_test_suite._time_end - self.act_test_suite._time_start
        data = {
            "ts_name": self.__get_ts_name(),
            "tc_name": self.__get_tc_name(),
            "kw_calls": self.act_test_suite.quantity,
            "kw_fails": self.act_test_suite.failed_kws,
            "py_version": self.act_test_suite.py_version,
            "rf_version": self.act_test_suite.rf_version,
            "os": self.act_test_suite.os,
            "plugins": self.act_test_suite.plugin_list,
            "ue_models": self.act_test_suite.ue_models,
            "ue_pc_ips": self.act_test_suite.ue_pc_ip_list,
            "ue_pc_os": self.act_test_suite.ue_pc_os_list,
            "ue_pc_python": self.act_test_suite.ue_pc_python_list,
            "ue_pc_proxy": self.act_test_suite.ue_pc_proxy_list,
            "ue_pc_access": self.act_test_suite.ue_pc_access_list,
            "ts_duration": f'{self.act_test_suite.duration:.2f}',
            "ts_status": self.act_test_suite.status,
            "level": "TS",
            "rf_file": self.act_test_suite.robot_file,
        }
        if self.act_test_suite.quantity:  # TS which does not use any ute_ue KW suppose to be skipped with file logging
            log_kw_data(data, message="TS")

    def _get_plugin_version(self):
        name = "mtk" if self.plugin_name == "mediatek" else self.plugin_name
        dists = [(dist['name'], dist['version']) for dist in DistributionsCache.pip_distributions_with_versions()]
        for package_name, version in dists:
            try:
                if "taf.ue." in package_name and name in package_name.split(".")[2]:
                    return version
            except IndexError:
                continue
        return "0.0.0.0"

    def __get_ts_name(self):
        """Get test suite name from cached or environment variable."""
        ts_name = self.test_suite_name if self.test_suite_name else os.environ.get(ENV_TS_NAME)
        return ts_name if ts_name else "Unknown"

    def __get_tc_name(self):
        """Get test case name from cached or environment variable."""
        tc_name = self.test_case_name if self.test_case_name else os.environ.get(ENV_TC_NAME)
        return tc_name if tc_name else "Unknown"

    def __update_platform_data_and_get(self):
        """Update platform data and get platform info."""
        os_release = get_windows_version() or platform.release()
        self._vm_platform_info = self._vm_platform_info if self._vm_platform_info else \
            f"{platform.system()}, {os_release}, {platform.architecture()}"
        if not self._vm_distro_info and "Linux" in self._vm_platform_info:
            self._vm_distro_info = platform.freedesktop_os_release().get("PRETTY_NAME") \
                if hasattr(platform, "freedesktop_os_release") else None
        return f"{self._vm_platform_info}, {self._vm_distro_info}" if self._vm_distro_info else \
            self._vm_platform_info

    def __get_ue_kw_metadata(self, ue_alias: str, plugin_name=None, plugin_version=None):
        """Get KW use to ute_ue.kw_data."""
        data = {
            'kw_name': self.kw_name if self.kw_name else "Unknown",
            'kw_duration': f'{self.kw_duration:.2f}',
            'ts_name': self.__get_ts_name(),
            'tc_name': self.__get_tc_name(),
            'logfile': f"{os.getcwd()}/log.html",
            'os': self.__update_platform_data_and_get(),
            'py_version': sys.version.split(" ")[0],
            'plugin_name': plugin_name if plugin_name else "Unknown",
            'plugin_version': plugin_version if plugin_version else "Unknown",
            'rf_version': RF_VERSION,
            'libs': self.__get_vm_libs(),
            'ue_pc': self.__get_ue_pc_metadata(ue_alias),
        }
        ue_data = self.__get_ue_data(ue_alias)
        if ue_data:
            ue_data["model"] = ue_data["model"] if ue_data.get("model") else "Unknown"
            data.update({"ue_data": ue_data})
        return data

    def __get_ue_pc_metadata(self, ue_alias):
        """Get UE PC metadata."""
        diag_data = self._diagnostic_data.get(ue_alias, {})
        py_data = diag_data.get("python", {})
        # Compare access_name with available plugins; by default use 'plugin' data
        plugin_data = diag_data.get("plugin", {})
        for plugin in [val for key, val in diag_data.items() if str(key).startswith("plugin")]:
            if plugin.get("name", "").lower() == self.access_name:
                plugin_data = plugin
                break
        pip_list = py_data.get("pip_list", [])
        libs_moler = [lib for lib in pip_list if "moler" in lib]
        return {"os": diag_data.get("os", None),
                "ip": diag_data.get("ue_pc_ip", None),
                "port": diag_data.get("ue_pc_port", 80),
                "python_version": py_data.get("version", "").split(" ")[0],
                "cygwin": diag_data.get("cygwin", None),
                "proxy_version": diag_data.get("version", None),
                "access_name": plugin_data.get("name", None),
                "access_version": plugin_data.get("details", {}).get("version", None),
                "pwd": diag_data.get("pwd", None),
                "user": diag_data.get("user", None),
                "libs": {"taf": self.__get_taf_libs(pip_list),
                         "moler": libs_moler[0] if len(libs_moler) > 0 else None,
                         }
                }

    def __get_taf_libs(self, pip_list: list) -> list:
        """Get TAF libs from pip list."""
        duplicated_names = {"taf.ue.proxy", f"taf.ue.proxy.access.{self.access_name}"}
        return [lib for lib in pip_list if lib.startswith("taf") and lib.split("==")[0] not in duplicated_names]

    def __get_vm_libs(self) -> dict:
        """Get VM libs info for KW metadata."""
        undesired_taf_libs = {
            f"taf.ue.{self.plugin_name}", "taf.ue.tm500", "taf.ue.prisma", "taf.ue.plugin", "taf.ue.pioneer",
            "taf.ue.airphone", "taf.config.cbts", "taf.config.scf", "taf.config.wts"
        }
        desired_taf_libs = {"taf.ue", "taf.config", "taf.internal.qualcomm."}

        taf_libs = [
            f"{lib['name']}=={lib['version']}"
            for lib in DistributionsCache.pip_distributions_with_versions()
            if any(str(lib['name']).startswith(desired) for desired in desired_taf_libs)
               and not any(str(lib['name']).startswith(undesired) for undesired in undesired_taf_libs)
        ]
        ute_libs = [
            f"{lib['name']}=={lib['version']}" for lib in DistributionsCache.pip_distributions_with_versions()
            if str(lib).startswith("ute-ue") or str(lib).startswith("ute-common-abstract")
        ]
        libs_moler = [f"{lib['name']}=={lib['version']}" for lib in DistributionsCache.pip_distributions_with_versions()
                      if "moler" in str(lib)]
        return {"taf": taf_libs,
                "ute": ute_libs,
                "moler": libs_moler[0] if len(libs_moler) > 0 else None,
                }

    def __get_ue_data(self, ue_alias) -> dict:
        """Get UE Info selected items for KW metadata."""
        ues_data = self._diagnostic_data.get(ue_alias, {}).get("ues", {})
        ue_id = self._diagnostic_data.get(ue_alias, {}).get("ue_id", None)
        ue_model = ues_data.get(ue_id, {}).get("model")
        ue_android_version = ues_data.get(ue_id, {}).get("android_version")
        ue_naa_version = ues_data.get(ue_id, {}).get("naa_version")
        ue_data = self._ue_data.get(ue_alias, {'model': ue_model} if ue_model else {})

        if ue_data:
            # Merge 'os version' items
            os_ver = _merge_str_vals(ue_data.pop("os_version") if "os_version" in ue_data else None,
                                     ue_data.pop("ue_os_ver") if "ue_os_ver" in ue_data else None,
                                     ue_data.pop("android_ver") if "android_ver" in ue_data else None,
                                     ue_android_version)
            if os_ver:
                ue_data.update({"os_ver": os_ver})

            # Merge 'name' items
            name = _merge_str_vals(ue_data.pop("name") if "name" in ue_data else None,
                                   ue_data.pop("commercial_name") if "commercial_name" in ue_data else None)
            if name:
                ue_data.update({"name": name})

            # Merge 'mobile_app_version' item into shorten name
            naa = _merge_str_vals(ue_data.pop("mobile_app_version") if "mobile_app_version" in ue_data else None,
                                  ue_naa_version)
            if naa:
                ue_data.update({"naa_ver": naa})

            # Merge 'device_model' item into shorten name, get data from diagnostic data 'ues' dict
            model = ue_data.pop("device_model") if "device_model" in ue_data else ue_model
            if model:
                ue_data.update({"model": model})
        return ue_data

    def _filter_libraries(self, report):
        """Filter libraries from metadata report (dict)."""
        filtered_libs = []
        libraries = ["taf.ue==", "ute-ue==", "moler==", "taf.config.testline==", "taf.ue.rpc.jsonrpc=="]

        for libs in report.get('libs', {}).values():
            if isinstance(libs, list):
                for lib in libs:
                    if any(substring in lib for substring in libraries or []):
                        filtered_libs.append(lib)
            elif libs and any(substring in libs for substring in libraries or []):
                filtered_libs.append(libs)

        return filtered_libs

    def format_html_info(self, report, error=None, error_nr=1):
        """
        Formats the kw data report and error information into an HTML table.

        :param report: dict: kw data report
        :param error: Exception: error object
        :param error_nr: int: error number
        :return: str: formatted report
        """
        report = dict(report or {})
        report['libs'] = self._filter_libraries(report)
        html_report = HtmlReport(report, error, error_nr)
        return html_report.generate_html_report()

    def format_json_info(self, report, error=None):
        """
        Formats the kw data report and error information into a JSON object.

        :param report: dict: kw data report
        :param error: Exception: error object
        :return: dict: formatted report
        """
        report = dict(report or {})
        report['libs'] = self._filter_libraries(report)
        json_report = JsonReport(report, error)
        return json_report.generate_json_report()

    def format_info(self, report, error=None, error_nr=1):
        """
        Formats the kw data report and error information into either HTML or JSON format.

        :param report: dict: kw data report
        :param error: Exception: error object
        :param error_nr: int: error number
        :return: str or dict: formatted report
        """
        from packaging import version
        if version.parse(RF_VERSION) >= version.parse("7.4"):
            return self.format_html_info(report, error, error_nr)
        return self.format_json_info(report, error)
